-- UGO Empresas is a D12-owned product readiness flow, never a new department.
create table if not exists public.ugo_empresas_readiness(id uuid primary key default gen_random_uuid(),product_key text not null unique default 'UGO_EMPRESAS',owner_department_id integer not null default 12 check(owner_department_id=12),stage text not null default 'SPEC' check(stage in('SPEC','ISOLATED_IMPLEMENTATION','TEST_LOAD','CROSS_FUNCTION_VALIDATION','QA_GATE','PILOT_READY','PILOT','PRODUCTION_AUTHORIZED')),status text not null default 'BLOCKED' check(status in('BLOCKED','IN_PROGRESS','READY')),blockers jsonb not null default '["CUSTOMER_1_CORE_NOT_STABLE"]'::jsonb,metrics jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),updated_by uuid);
create table if not exists public.ugo_empresas_demands(id uuid primary key default gen_random_uuid(),company_ref text not null,skill text not null,quantity integer not null check(quantity>0),place text not null,starts_at timestamptz not null,duration_minutes integer not null check(duration_minutes>0),requirements jsonb not null default '{}'::jsonb,status text not null default 'DRAFT',created_at timestamptz not null default now());
create table if not exists public.ugo_empresas_slots(id uuid primary key default gen_random_uuid(),demand_id uuid not null references public.ugo_empresas_demands(id) on delete cascade,slot_index integer not null,provider_id uuid,backup_provider_id uuid,status text not null default 'OPEN',reconfirmed_at timestamptz,checked_in_at timestamptz,validated_minutes integer,replacement_reason text,unique(demand_id,slot_index));
alter table public.ugo_empresas_readiness enable row level security;alter table public.ugo_empresas_demands enable row level security;alter table public.ugo_empresas_slots enable row level security;
do $$begin create policy empresas_superadmin_readiness on public.ugo_empresas_readiness for select to authenticated using(private.is_superadmin());create policy empresas_superadmin_demands on public.ugo_empresas_demands for select to authenticated using(private.is_superadmin());create policy empresas_superadmin_slots on public.ugo_empresas_slots for select to authenticated using(private.is_superadmin());exception when duplicate_object then null;end$$;
grant select on public.ugo_empresas_readiness,public.ugo_empresas_demands,public.ugo_empresas_slots to authenticated;
insert into public.ugo_empresas_readiness(product_key)values('UGO_EMPRESAS')on conflict(product_key)do nothing;